<?php
declare(strict_types=1);
require __DIR__ . '/lib/customers.php';
$configPath = '/volume1/homes/jdrury/.druryit-support/config.php';
if (!is_file($configPath)) { http_response_code(503); exit('Ticket desk is not configured.'); }
$config = require $configPath;
$key = (string) ($_REQUEST['key'] ?? '');
if ($key === '' || !hash_equals((string) ($config['desk_key'] ?? ''), $key)) { http_response_code(404); exit('Not found.'); }
$root = (string) ($config['tickets_dir'] ?? '');
if ($root === '' || !is_dir($root)) { http_response_code(503); exit('Ticket storage is unavailable.'); }
$statuses = ['All', 'Open', 'In progress', 'Closed', 'Archived'];
$filter = (string) ($_REQUEST['filter'] ?? 'All'); if (!in_array($filter, $statuses, true)) $filter = 'All';
$profiles = loadCustomerProfiles($config);
function h(string $v): string { return htmlspecialchars($v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function ticketPath(string $root, string $id): ?string { return preg_match('/^DIT-[0-9]{8}-[0-9]{6}-[A-F0-9]{6}$/', $id) ? $root . DIRECTORY_SEPARATOR . $id . DIRECTORY_SEPARATOR . 'ticket.json' : null; }
function loadTicket(string $root, string $id): ?array { $p=ticketPath($root,$id); $t=$p&&is_file($p)?json_decode((string)file_get_contents($p),true):null; return is_array($t)?$t:null; }
function saveTicket(string $root, array $ticket): void { $p=ticketPath($root,(string)$ticket['ticket_id']); if ($p) file_put_contents($p,json_encode($ticket,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES).PHP_EOL,LOCK_EX); }
function deleteTicket(string $root, string $id): bool { $p=ticketPath($root,$id); $base=realpath($root); $dir=$p?realpath(dirname($p)):false; if(!$base||!$dir||strpos($dir,$base.DIRECTORY_SEPARATOR)!==0||!is_dir($dir))return false; $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST); foreach($it as $x){$x->isDir()&&!$x->isLink()?rmdir($x->getPathname()):unlink($x->getPathname());} return rmdir($dir); }
if (isset($_GET['download'])) { $t=loadTicket($root,(string)$_GET['download']); $i=filter_var($_GET['attachment']??null,FILTER_VALIDATE_INT); if($t===null||$i===false||!isset($t['attachments'][$i])){http_response_code(404);exit('Not found.');} $a=$t['attachments'][$i]; $p=dirname((string)ticketPath($root,$t['ticket_id'])).DIRECTORY_SEPARATOR.$a['stored_name']; if(!is_file($p)){http_response_code(404);exit('Attachment unavailable.');} header('Content-Type: '.$a['mime']);header('Content-Length: '.filesize($p));header('Content-Disposition: attachment; filename="'.str_replace('"','',$a['name']).'"');readfile($p);exit; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') { $id=(string)($_POST['ticket_id']??''); if(($_POST['action']??'')==='delete'){deleteTicket($root,$id);header('Location: desk.php?key='.rawurlencode($key).'&filter='.rawurlencode($filter));exit;} $t=loadTicket($root,$id);$status=(string)($_POST['status']??'');if($t!==null&&in_array($status,array_slice($statuses,1),true)){$t['status']=$status;$t['updated_at']=gmdate('c');$t['history'][]=['at'=>gmdate('c'),'status'=>$status,'note'=>mb_substr(trim((string)($_POST['note']??'')),0,1000)];saveTicket($root,$t);}header('Location: desk.php?key='.rawurlencode($key).'&filter='.rawurlencode($filter).'&ticket='.rawurlencode($id));exit; }
$tickets=[]; foreach(glob($root.DIRECTORY_SEPARATOR.'DIT-*'.DIRECTORY_SEPARATOR.'ticket.json')?:[] as $p){$t=json_decode((string)file_get_contents($p),true);if(is_array($t))$tickets[]=$t;} usort($tickets,static fn(array $a,array $b):int=>strcmp((string)($b['updated_at']??''),(string)($a['updated_at']??'')));
$shown=$filter==='All'?$tickets:array_values(array_filter($tickets,static fn(array $t):bool=>($t['status']??'Open')===$filter));
$selected=isset($_GET['ticket'])?loadTicket($root,(string)$_GET['ticket']):($shown[0]??null); if($selected!==null&&$filter!=='All'&&($selected['status']??'Open')!==$filter)$selected=$shown[0]??null;
$customer=$selected===null?null:($profiles[(string)($selected['customer_id']??'')]??null);$logo=customerLogoDataUri($customer);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DruryIT Ticket Desk</title><style>body{margin:0;background:#f5f7fa;color:#1d2939;font:15px system-ui}header{background:#12345b;color:#fff;padding:20px 28px}h1{margin:0;font-size:24px}.layout{display:grid;grid-template-columns:380px 1fr;gap:20px;padding:20px;max-width:1440px;margin:auto}.panel{background:#fff;border:1px solid #d9e1ea;border-radius:10px;overflow:hidden}.summary,.filters{padding:14px 16px;border-bottom:1px solid #d9e1ea;font-weight:600}.filters{display:flex;gap:8px;align-items:center}.ticket{display:block;color:inherit;text-decoration:none;padding:14px 16px;border-bottom:1px solid #eef1f4}.ticket:hover,.ticket.active{background:#eaf3ff}.id{font-weight:700}.meta{font-size:13px;color:#667085;margin-top:4px}.status{display:inline-block;border-radius:99px;padding:3px 8px;font-size:12px;font-weight:700;background:#e8f1fc;color:#14599c}.closed{background:#e7f6ec;color:#18713a}.archived{background:#eceff3;color:#475467}.detail{padding:28px}.heading{display:flex;align-items:center;gap:12px}.logo{max-width:96px;max-height:64px;object-fit:contain}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:18px 0}.box{background:#f8fafc;padding:12px;border-radius:7px}.label{font-size:12px;color:#667085;text-transform:uppercase;font-weight:700}.problem{white-space:pre-wrap;line-height:1.5;border-left:3px solid #1e6db2;padding-left:14px}.actions{margin-top:24px;border-top:1px solid #e6eaf0;padding-top:18px}.actions select,.actions textarea,.actions button,.filters select,.filters button{font:inherit;padding:9px;border:1px solid #b8c4d1;border-radius:6px}.actions textarea{width:100%;box-sizing:border-box;margin:10px 0;min-height:70px}.actions button,.filters button{background:#1666ad;color:#fff;border:0;cursor:pointer}.danger{background:#b42318!important;margin-left:8px}@media(max-width:800px){.layout{grid-template-columns:1fr}.grid{grid-template-columns:1fr}}</style></head><body><header><h1>DruryIT Ticket Desk</h1></header><main class="layout"><aside class="panel"><div class="summary">Tickets</div><form class="filters" method="get"><input type="hidden" name="key" value="<?=h($key)?>"><label>Status <select name="filter"><?php foreach($statuses as $s):?><option <?=$filter===$s?'selected':''?>><?=h($s)?></option><?php endforeach;?></select></label><button>Filter</button></form><?php if(!$shown):?><p class="meta" style="padding:0 16px">No matching tickets.</p><?php endif;?><?php foreach($shown as $t):$active=$selected&&$t['ticket_id']===$selected['ticket_id'];$st=(string)($t['status']??'Open');?><a class="ticket <?=$active?'active':''?>" href="?key=<?=rawurlencode($key)?>&filter=<?=rawurlencode($filter)?>&ticket=<?=rawurlencode($t['ticket_id'])?>"><div class="id"><?=h($t['ticket_id'])?> <span class="status <?=$st==='Closed'?'closed':($st==='Archived'?'archived':'')?>"><?=h($st)?></span></div><div><?=h($t['customer_name']??$t['client_name']??'Unknown customer')?> · <?=h($t['computer']??'Unknown computer')?></div><div class="meta"><?=h($t['updated_at']??'')?></div></a><?php endforeach;?></aside><section class="panel detail"><?php if($selected===null):?><p>No matching portal tickets.</p><?php else:?><div class="heading"><?php if($logo!==''):?><img class="logo" src="<?=h($logo)?>" alt="Customer logo"><?php endif;?><h2><?=h($selected['ticket_id'])?> <span class="status <?=($selected['status']??'')==='Closed'?'closed':(($selected['status']??'')==='Archived'?'archived':'')?>"><?=h($selected['status']??'Open')?></span></h2></div><div class="grid"><div class="box"><div class="label">Customer / client</div><?=h($selected['customer_name']??$selected['client_name']??'')?></div><div class="box"><div class="label">Contact</div><?=h($selected['contact_name']??$selected['user']??'')?></div><div class="box"><div class="label">Computer</div><?=h($selected['computer']??'')?></div><div class="box"><div class="label">Priority / best time</div><?=h($selected['priority']??'')?> · <?=h($selected['best_time']??'')?></div></div><h3>Issue</h3><div class="problem"><?=h($selected['problem']??'')?></div><h3>Attachments</h3><?php if(empty($selected['attachments'])):?>None<?php else:foreach($selected['attachments'] as $i=>$a):?><a href="?key=<?=rawurlencode($key)?>&filter=<?=rawurlencode($filter)?>&download=<?=rawurlencode($selected['ticket_id'])?>&attachment=<?=$i?>"><?=h($a['name'])?></a> <?php endforeach;endif;?><h3>History</h3><ul><?php foreach(($selected['history']??[]) as $e):?><li><strong><?=h($e['status']??'')?></strong> · <?=h($e['at']??'')?><?=empty($e['note'])?'':' — '.h($e['note'])?></li><?php endforeach;?></ul><form class="actions" method="post"><input type="hidden" name="key" value="<?=h($key)?>"><input type="hidden" name="filter" value="<?=h($filter)?>"><input type="hidden" name="ticket_id" value="<?=h($selected['ticket_id'])?>"><label>Status <select name="status"><?php foreach(array_slice($statuses,1) as $s):?><option <?=($selected['status']??'')===$s?'selected':''?>><?=h($s)?></option><?php endforeach;?></select></label><textarea name="note" placeholder="Optional update note"></textarea><button name="action" value="save">Save ticket update</button><button class="danger" name="action" value="delete" onclick="return confirm('Permanently delete this ticket and its attachments?');">Delete ticket</button></form><?php endif;?></section></main></body></html>
